def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 100:
        return 'C'
    my, opp = zip(*history)
    last_opp = opp[-1]
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'
    if n == 2:
        if opp[0] == 'C' and opp[1] == 'C':
            return 'C'
        if opp[0] == 'C' and opp[1] == 'D':
            return 'D'
        if opp[0] == 'D' and opp[1] == 'C':
            return 'D'
        return 'C'
    defections = sum(1 for a in opp if a == 'D')
    ratio = defections / n
    recent = opp[-10:]
    recent_def = sum(1 for a in recent if a == 'D')
    if ratio < 0.12:
        return 'C'
    if ratio > 0.55:
        if last_opp == 'D':
            return 'D'
        return 'D' if rng.random() < 0.75 else 'C'
    if recent_def >= 5:
        return 'D'
    if recent_def == 0:
        return 'C'
    if last_opp == 'D':
        if n >= 3 and opp[-2] == 'D' and opp[-3] == 'D':
            return 'D'
        return 'D' if rng.random() < 0.65 else 'C'
    if ratio < 0.3:
        return 'C'
    return 'C' if rng.random() < 0.8 else 'D'

